### Quick “hardening” patch you can apply today

```js
// app.js – hardening example
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet());
app.use(cors({ origin: ['https://my‑trusted‑site.com'] })); // adjust whitelist
app.use(express.json({ limit: '1mb' }));

// Basic rate limiting (adjust thresholds for your traffic)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                 // limit each IP to 100 requests per window
});
app.use(limiter);

// Health check – keep public
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example protected endpoint – **remove** or protect in production
app.get('/users', (req, res) => {
  // In production you would require auth and NOT expose emails.
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ];
  res.json(users);
});

// Centralised error handling
app.use((err, _req, res, _next) => {
  console.error(err); // consider structured logging
  res.status(500).json({ error: 'Internal Server Error' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

Add the required dependencies:

```bash
npm init -y
npm install express helmet express-rate-limit cors
```

Commit a lockfile (`npm i --package-lock`) and add `.env*` to `.gitignore`.

