// app.js – security‑enhanced version
// ---------------------------------------------------
// Express application with common security hardening
// ---------------------------------------------------

const express = require('express');
const helmet = require('helmet');          // Secure HTTP headers
const cors = require('cors');              // CORS control
const rateLimit = require('express-rate-limit'); // Rate limiting
const morgan = require('morgan');          // Request logging (helps detect abuse)

const app = express();

// -------------------------------------------------------------------
// Global middle‑wares
// -------------------------------------------------------------------
app.use(helmet());                         // Adds a wide set of security headers
app.use(cors({                               // Example: allow only trusted origins
  origin: process.env.ALLOWED_ORIGIN || '*', // adjust as needed
  methods: ['GET', 'POST', 'OPTIONS'],
}));
app.use(express.json({ limit: '100kb' })); // Body size limit (prevent DoS)
app.use(morgan('combined'));               // Standardised request logs

// -------------------------------------------------------------------
// Rate limiter – apply globally or per‑route as desired
// -------------------------------------------------------------------
const apiLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 100,            // max 100 requests per IP per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/users', apiLimiter); // more aggressive on sensitive endpoints

// -------------------------------------------------------------------
// Routes
// -------------------------------------------------------------------
app.get('/health', (req, res) => {
  // Return minimal health data – avoid leaking precise timestamps if not needed.
  res.json({ status: 'ok' });
});

app.get('/users', (req, res) => {
  // In a real app this would be protected (auth, RBAC) and data fetched from a DB.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com' },
  ];
  res.json(users);
});

// -------------------------------------------------------------------
// Error handling (must be after all routes)
// -------------------------------------------------------------------
app.use((err, req, res, next) => {
  // Log the error internally
  console.error(err);

  // Do not leak stack traces in production
  const response = {
    error: 'Internal Server Error',
  };
  if (process.env.NODE_ENV !== 'production') {
    response.details = err.message;
  }
  res.status(500).json(response);
});

// -------------------------------------------------------------------
// Server start
// -------------------------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

### What each addition does

| Addition | Purpose |
|----------|---------|
| `helmet()` | Injects `X‑Content‑Type‑Options`, `X‑Frame‑Options`, `Content‑Security‑Policy`, `Strict‑Transport‑Security`, etc. |
| `cors()` | Explicitly defines which origins may call the API; default `*` is still safe for a public API, but you can restrict it later. |
| `express.json({ limit: '100kb' })` | Prevents huge JSON payloads that could exhaust memory. |
| `morgan('combined')` | Structured request logging – useful for audit trails and detecting abuse. |
| `express-rate-limit` | Throttles repeated requests and mitigates brute‑force / DoS. |
| Minimal health payload | Removes timestamp leakage; keep only what monitoring requires. |
| Centralised error handler | Guarantees JSON error responses and prevents stack‑trace leakage in production. |
| `process.env.PORT` | Allows the runtime (e.g., Docker, PaaS) to dictate which port the server binds to. |
| `process.env.NODE_ENV` check | Avoids exposing internal error details outside of dev. |

