## 3. Suggested Refactored `app.js`

Below is a **minimal** yet security‑hardened version that addresses the above gaps while preserving existing functionality.

```js
// app.js – Security‑hardened minimal Express server
// -------------------------------------------------

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');

const app = express();

// ----- Middleware -----
app.use(helmet());                       // security headers
app.use(cors({ origin: ['https://mytrusteddomain.com'] })); // lock down origins
app.use(express.json({ limit: '100kb' })); // body size limit (if needed)
app.use(morgan('combined'));            // request logging

// Simple rate limiter: 100 req / 15 min per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ----- Routes -----
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // In a real app, data would come from a DB with proper access controls
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ----- 404 handler -----
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// ----- Global error handler -----
app.use((err, req, res, next) => {
  console.error(err); // consider structured logging in prod
  res.status(500).json({ error: 'Internal Server Error' });
});

// ----- Server start -----
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.info(`🔹 Server running on port ${PORT}`);
});

module.exports = app;
```

**Key Additions**

| Feature | Library | Reason |
|---------|---------|--------|
| **Helmet** | `helmet` | Sets a robust set of HTTP security headers automatically. |
| **CORS** | `cors` | Restricts which origins may call the API. |
| **Rate Limiting** | `express-rate-limit` | Thwarts brute‑force and DoS attempts. |
