```js
// app.js – environment‑driven configuration
// -------------------------------------------------

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');

const app = express();

// ---- Config ---------------------------------------------------
// Port the server will listen on (default 3000)
const PORT = parseInt(process.env.PORT, 10) || 3000;

// CORS allowed origins – comma‑separated list, e.g. "https://example.com,https://api.example.com"
// If not set, default to a safe single‑origin (you should replace it with your real domain)
const corsOriginsEnv = process.env.CORS_ORIGINS || 'http://localhost:3000';
const CORS_ORIGINS = corsOriginsEnv.split(',').map(o => o.trim());

// Optional user data source (JSON string or path to a JSON file)
// If not supplied, fallback to the built‑in demo array.
let USERS;
if (process.env.USERS_DATA) {
  try {
    // 1️⃣ If USERS_DATA looks like a path to a file, read it.
    const fs = require('fs');
    const path = require('path');
    const possiblePath = path.resolve(process.env.USERS_DATA);
    if (fs.existsSync(possiblePath)) {
      USERS = JSON.parse(fs.readFileSync(possiblePath, 'utf8'));
    } else {
      // 2️⃣ Otherwise treat it as a raw JSON string.
      USERS = JSON.parse(process.env.USERS_DATA);
    }
  } catch (e) {
    console.warn('⚠️ Unable to parse USERS_DATA – falling back to demo data.');
    USERS = null;
  }
}
if (!USERS) {
  // Demo data (keep for local testing only)
  USERS = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com' },
  ];
}

// ---- Middleware ------------------------------------------------
app.use(helmet());

app.use(
  cors({
    origin: CORS_ORIGINS,
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  })
);

// Basic request logging (use a more sophisticated logger in prod)
app.use(morgan('combined'));

// Simple rate limiter – adjust limits per your threat model
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // limit each IP to 100 requests per windowMs
    standardHeaders: true,
    legacyHeaders: false,
  })
);

// ---- Routes ----------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // In a real service you'd pull this from a DB or external API.
  res.json(USERS);
});

// ---- 404 & error handling ---------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

app.use((err, req, res, next) => {
  console.error(err);
  // Do **not** expose stack traces to the client in production.
  res.status(500).json({ error: 'Internal Server Error' });
});

// ---- Server start ------------------------------------------------
app.listen(PORT, () => {
  console.info(`🚀 Server listening on port ${PORT}`);
});

module.exports = app;
```

